import json

# Import users_data generated by generate_seed_500
from generate_seed_500 import users_data

doc_lines = []
doc_lines.append("# Seeded Test Users and Mock Data (500 Users)")
doc_lines.append("")
doc_lines.append("This document contains the comprehensive catalog of 500 seeded users with diverse mock data across all 12 operational departments at ICC Sydney.")
doc_lines.append("")
doc_lines.append("## Credential Pattern")
doc_lines.append("For all test users, credentials follow the standard development pattern:")
doc_lines.append("- **Email**: `test{N}@test.com` (from `test1@test.com` to `test500@test.com`)")
doc_lines.append("- **Password**: `test{N}`")
doc_lines.append("- **Authentication**: All accounts have confirmed emails and bcrypt password hashes in `auth.users`, enabling direct sign-in.")
doc_lines.append("")
doc_lines.append("---")
doc_lines.append("")
doc_lines.append("## Distribution Overview")
doc_lines.append("")

# Dept stats
dept_counts = {}
for u in users_data:
    dept_counts[u['dept_name']] = dept_counts.get(u['dept_name'], 0) + 1

doc_lines.append("### Headcount by Department")
doc_lines.append("| Department | Count | Proportion |")
doc_lines.append("| :--- | :--- | :--- |")
for dept, count in sorted(dept_counts.items(), key=lambda x: x[1], reverse=True):
    doc_lines.append(f"| {dept} | {count} | {count / 5.0:.1f}% |")

doc_lines.append("")

# Employment status stats
emp_counts = {}
for u in users_data:
    emp_counts[u['emp_status']] = emp_counts.get(u['emp_status'], 0) + 1

doc_lines.append("### Headcount by Employment Type")
doc_lines.append("| Employment Type | Count | Standard Hours | Pay Basis |")
doc_lines.append("| :--- | :--- | :--- | :--- |")
doc_lines.append(f"| Full-Time | {emp_counts.get('Full-Time', 0)} | 38h / week | Salaried & EBA Level 3-7 |")
doc_lines.append(f"| Part-Time | {emp_counts.get('Part-Time', 0)} | 20-31h / week | EBA Level 2-4 |")
doc_lines.append(f"| Casual | {emp_counts.get('Casual', 0)} | 0h contracted (hourly) | EBA Level 1-4 |")

doc_lines.append("")

# Access levels stats
access_counts = {}
for u in users_data:
    access_counts[u['access_level']] = access_counts.get(u['access_level'], 0) + 1

doc_lines.append("### Access Levels")
doc_lines.append("| Access Level | Scope | Headcount | Target Roles |")
doc_lines.append("| :--- | :--- | :--- | :--- |")
doc_lines.append(f"| `alpha` | Base Staff | {access_counts.get('alpha', 0)} | Team Members, Attendants, Crew, Kitchen Hands, Ushers |")
doc_lines.append(f"| `beta` | Sub-department Lead | {access_counts.get('beta', 0)} | Team Leaders, Senior Technicians, Lead Ushers |")
doc_lines.append(f"| `gamma` | Sub-department Manager | {access_counts.get('gamma', 0)} | Supervisors, Assistant Managers, Sous Chefs |")
doc_lines.append(f"| `delta` | Department Manager | {access_counts.get('delta', 0)} | Department Managers, Executive Chefs, Floor Managers |")

doc_lines.append("")
doc_lines.append("---")
doc_lines.append("")
doc_lines.append("## Mock Data Dimensions Included")
doc_lines.append("Each seeded user profile includes complete relational and compliance data:")
doc_lines.append("- **Personal Details**: Full name, employee code (`ICC-1001` to `ICC-1500`), date of birth (ages 19-61), Australian phone numbers, emergency contact details.")
doc_lines.append("- **Compliance & EBA Terms**: Rest gap agreement (8h vs 10h), continuous service dates, employment statuses, contracted weekly hours, 4-week cycle anchors.")
doc_lines.append("- **Skills & Proficiencies**: 2 to 5 verified skills per user (e.g. RSA, First Aid Lv2, Food Handling, Sound Engineering, Crowd Management, ES-GOLD, Barista Basics) with proficiency levels (`Novice`, `Competent`, `Proficient`, `Expert`).")
doc_lines.append("- **Licenses & Work Rights**: Mandatory and professional licenses (`RSA`, `Food Safety Certificate`, `Working With Children Check`, `Driver License - C`, `Forklift License`) with verified statuses and student visa work limits (`license_type = 'WorkRights'`).")
doc_lines.append("- **First Aid Appointments**: Qualified first aid officers appointed under ICC Sydney organization.")
doc_lines.append("- **Availability Rules**: Weekly recurring availability patterns with day-by-day availability slots automatically generated for Casual and Part-Time staff.")
doc_lines.append("- **Reliability & Performance Metrics**: Historical attendance, on-time percentage (88%-100%), cancellation rates, punctuality scores, clock-in metrics.")
doc_lines.append("- **Preferences**: JSONB shift preferences (morning/afternoon/night), uniform sizes, and notification preferences.")
doc_lines.append("")
doc_lines.append("---")
doc_lines.append("")
doc_lines.append("## Complete 500 User Catalog")
doc_lines.append("")
doc_lines.append("| # | Name | Email | Password | Code | Department | Subdepartment | Role | Type | Access | User ID |")
doc_lines.append("| :--- | :--- | :--- | :--- | :--- | :--- | :--- | :--- | :--- | :--- | :--- |")

for u in users_data:
    doc_lines.append(
        f"| {u['idx']} | {u['first_name']} {u['last_name']} | `{u['email']}` | `{u['password']}` | `{u['emp_code']}` | "
        f"{u['dept_name']} | {u['sub_dept_name']} | {u['role_name']} | {u['emp_status']} | `{u['access_level']}` | `{u['id']}` |"
    )

with open('seeded_users.md', 'w') as f_out:
    f_out.write("\n".join(doc_lines))

print(f"Updated seeded_users.md with all {len(users_data)} users!")
